name: CI

on:
  push:
    branches: [main]
  pull_request:
  workflow_dispatch:

permissions:
  contents: read

concurrency:
  group: ci-${{ github.ref }}
  cancel-in-progress: true

jobs:
  quality:
    name: Go, React, E2E, and offline checks
    runs-on: ubuntu-24.04
    timeout-minutes: 25
    steps:
      - name: Check out source
        uses: actions/checkout@v4

      - name: Set up Go
        uses: actions/setup-go@v5
        with:
          go-version-file: go.mod
          cache: true

      - name: Set up Node.js
        uses: actions/setup-node@v4
        with:
          node-version: 22
          cache: npm
          cache-dependency-path: web/package-lock.json

      - name: Install frontend dependencies
        working-directory: web
        run: npm ci --no-audit --no-fund

      - name: Check formatting and lint
        run: |
          unformatted="$(find . -path './web' -prune -o -path './.git' -prune -o -type f -name '*.go' -print0 | xargs -0 gofmt -l)"
          test -z "$unformatted"
          npm --prefix web run lint

      - name: Run Go tests
        run: go test -race . ./cmd/... ./internal/... ./migrations/... ./openapi/...

      - name: Run React tests
        run: npm --prefix web test

      - name: Build and check offline frontend
        run: |
          npm --prefix web run build
          ./scripts/check-offline-assets.sh web/dist
          ./scripts/embed-web.sh

      - name: Build Go service
        run: go build -trimpath -buildvcs=false -o /tmp/appstore-ci ./cmd/server

      - name: Validate environment and documentation contracts
        run: |
          ./scripts/check-env-contract.sh
          ./scripts/check-docs.sh

      - name: Install Playwright browser
        working-directory: web
        run: npx playwright install --with-deps chromium

      - name: Run desktop and mobile E2E tests
        working-directory: web
        run: npm run test:e2e

      - name: Upload Playwright report on failure
        if: failure()
        uses: actions/upload-artifact@v4
        with:
          name: playwright-report
          path: web/playwright-report/
          if-no-files-found: ignore
          retention-days: 7

  image:
    name: Non-root offline image smoke test
    needs: quality
    runs-on: ubuntu-24.04
    timeout-minutes: 20
    steps:
      - name: Check out source
        uses: actions/checkout@v4

      - name: Set up Docker Buildx
        uses: docker/setup-buildx-action@v3

      - name: Build CI image
        run: |
          docker build --platform linux/amd64 --load \
            --build-arg VERSION=v0.0.0 \
            --build-arg COMMIT="${GITHUB_SHA}" \
            --build-arg BUILD_DATE="$(date -u +%Y-%m-%dT%H:%M:%SZ)" \
            --tag appstore:v0.0.0 .

      - name: Verify non-root image and embedded UI
        run: |
          test "$(docker image inspect --format '{{ .Config.User }}' appstore:v0.0.0)" = "appstore:appstore"
          ./scripts/smoke-image.sh appstore:v0.0.0
test("검토자는 앱 내용과 이전 검토를 보고 의견과 함께 결정한다", async ({
  page,
}) => {
  await installMockApi(page, { authenticated: true });
  await page.goto("/review/dddddddd-dddd-4ddd-8ddd-dddddddddddd");
  // The app's name is both the page title and the heading of its card, so the
  // page's own heading is the one to look at.
  await expect(
    page.getByRole("heading", { name: "Flow Studio", level: 1 }),
  ).toBeVisible();
  // What the decision rests on: the app itself, its guide, its security state
  // and what the last reviewer said.
  await expect(
    page.getByText("조직의 API와 이벤트를 연결해 업무 흐름을 구성합니다."),
  ).toBeVisible();
  await expect(page.getByText("Flow Studio 운영 가이드")).toBeVisible();
  await expect(page.getByText("보안 심의 완료")).toBeVisible();
  await expect(page.getByText(/사내망에서 열리지 않았습니다/)).toBeVisible();

  // A rejection needs a note; an approval may carry one.
  await page.getByRole("button", { name: /반려/ }).click();
  await expect(page.getByText(/사유를 입력하세요/)).toBeVisible();
  await page.getByLabel("검토 의견").fill("사내망 접속을 확인했습니다.");
  await page.getByRole("button", { name: /승인 및 게시/ }).click();
  await expect(page).toHaveURL(/\/review$/);
});

test("공개 앱 즐겨찾기는 소유자와 공개 목록에서 추가하고 즐겨찾기에서 해제한다", async ({
  page,
}) => {
  await installMockApi(page, { authenticated: true });
  for (const path of ["/my/apps", "/my", "/apps"]) {
    await page.goto(path);
    const add = page.getByRole("button", { name: "Agent Hub 즐겨찾기 추가" });
    await expect(add).toHaveAttribute("aria-pressed", "false");
    await add.click();
    await expect(
      page.getByRole("button", { name: "Agent Hub 즐겨찾기 해제" }),
    ).toHaveAttribute("aria-pressed", "true");
    expect(
      await page.evaluate(() =>
        JSON.parse(localStorage.getItem("appstore.favorites")!),
      ),
    ).toEqual(["agent-hub"]);
    await page.getByRole("link", { name: "즐겨찾기", exact: true }).click();
    await expect(page).toHaveURL("/favorites");
    await expect(
      page.getByRole("heading", { name: "Agent Hub" }),
    ).toBeVisible();
    const remove = page.getByRole("button", {
      name: "Agent Hub 즐겨찾기 해제",
    });
    await expect(remove).toHaveAttribute("aria-pressed", "true");
    await remove.click();
    await expect(page.getByRole("heading", { name: "Agent Hub" })).toHaveCount(
      0,
    );
    expect(
      await page.evaluate(() =>
        JSON.parse(localStorage.getItem("appstore.favorites")!),
      ),
    ).toEqual([]);
    await page.reload();
    await expect(
      page.getByRole("heading", { name: "즐겨찾기한 앱이 없습니다" }),
    ).toBeVisible();
  }
});
